    let root = std::path::Path::new(crate::model::storage::ROOT);
    let result = if combo {
        crate::model::combo_record::ComboLibrary::new(root.join("combos")).load(id)
            .map_err(|error| error.to_string()).and_then(ClipEditor::combo_file)
    } else {
