    PREVIEW_NOTICES.post(PreviewNotice::Failed {
        session: crate::runtime::macros::named_macros::session_revision(),
        revision: REVISION.load(Ordering::Acquire), message,
    });
    crate::runtime::ui::worker::wake();
}

